用法：
    python llm.py "你好"
    echo "你好" | python llm.py
"""
import configparser
import json
import sys
import urllib.error
import urllib.request
from pathlib import Path

CONFIG = Path(__file__).with_name("config.ini")


def ask(prompt):
    cfg = configparser.ConfigParser()
    cfg.read(CONFIG, encoding="utf-8")
    s = cfg["llm"]

    req = urllib.request.Request(
        s["base_url"].rstrip("/") + "/chat/completions",
        data=json.dumps({
            "model": s["model"],
            "messages": [{"role": "user", "content": prompt}],
        }).encode(),
        headers={
            "Content-Type": "application/json",
            "Authorization": "Bearer " + s["api_key"],
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=120) as resp:
            return json.load(resp)["choices"][0]["message"]["content"]
    except urllib.error.HTTPError as e:
        sys.exit("请求失败 HTTP %s: %s" % (e.code, e.read().decode("utf-8", "replace")))


def main():
    prompt = " ".join(sys.argv[1:]) or sys.stdin.read()
    if not prompt.strip():
        sys.exit('用法: python llm.py "你的提示词"')
    print(ask(prompt))


if __name__ == "__main__":
    main()
