{"content": """"终端版一次性对话大语言模型：打字 → 回复逐字流出 → 继续下一轮。配置读 config.ini。
每轮独立，不带上文（和弹窗版行为一致）。

运行：python llm_cli.py
退出：输入 exit / quit / q，空行回车，或按 Ctrl+C
"""
import sys
import time

from llm import TYPE_MS, ask_stream


def main():
    typing = sys.stdout.isatty()          # 终端里逐字流；被管道/重定向时直接快吐
    print("一次性对话大语言模型（输入 exit 退出）\n")
    while True:
        try:
            prompt = input("你：").strip()
        except (EOFError, KeyboardInterrupt):
            print()
            break
        if not prompt or prompt.lower() in ("exit", "quit", "q"):
            break
        print("AI：", end="", flush=True)
        try:
            for piece in ask_stream(prompt):
                if typing:
                    for ch in piece:
                        print(ch, end="", flush=True)
                        time.sleep(TYPE_MS)
                else:
                    print(piece, end="", flush=True)
        except SystemExit as e:           # ask_stream 用 sys.exit 报 HTTP 错误
            print("出错了：%s" % e)
        print("\n")
    print("再见。")


if __name__ == "__main__":
    main()
