{"content": "# -*- coding: utf-8 -*-
"""在真正的控制台窗口里启动「对话大模型 · 终端版」。

沙箱给每个进程挂的是隐藏伪控制台，直接 print 看不到窗口。
做法：FreeConsole 摘掉旧的 -> AllocConsole 申请一个真窗口 ->
把标准流换成 CONIN$/CONOUT$ -> 在同一个进程里跑 llm_cli.main()。
"""
import ctypes
import os
import sys

APP_DIR = r"D:\大语言模型\agent"
TITLE = "对话大模型 · 终端版"


class Tty:
    """让 isatty() 恒为 True，llm_cli 才会走逐字流式输出。"""

    def __init__(self, f):
        self._f = f

    def __getattr__(self, name):
        return getattr(self._f, name)

    def isatty(self):
        return True

    def reconfigure(self, **kw):
        try:
            self._f.reconfigure(**kw)
        except Exception:
            pass


def main():
    k32 = ctypes.windll.kernel32
    k32.FreeConsole()
    if not k32.AllocConsole():
        ctypes.windll.user32.MessageBoxW(None, "无法创建控制台窗口", "错误", 0)
        return 1

    k32.SetConsoleOutputCP(65001)
    k32.SetConsoleCP(65001)
    k32.SetConsoleTitleW(TITLE)

    try:
        sys.stdout.flush()
    except Exception:
        pass

    cin = open("CONIN$", "r", encoding="utf-8", errors="replace", newline="")
    cout = open("CONOUT$", "w", encoding="utf-8", errors="replace", buffering=1)
    sys.stdin = Tty(cin)
    sys.stdout = Tty(cout)
    sys.stderr = Tty(cout)

    os.chdir(APP_DIR)
    sys.path.insert(0, APP_DIR)

    try:
        import llm_cli
        llm_cli.main()
    except Exception as e:
        import traceback
        traceback.print_exc()
        print("\n启动失败：%r" % (e,))

    try:
        input("\n按回车关闭窗口...")
    except Exception:
        pass
    return 0


if __name__ == "__main__":
    sys.exit(main())
